'use client';

import { Challenge } from '@/data/types';

type ChallengeModalProps = {
  challenge: Challenge;
  index: number;
  total: number;

  choice: number | null;
  setChoice:(value:string | number)=>void

  shortAnswer: string;
  setShortAnswer: (value: string) => void;

  onSubmit: () => void;

  onContinue: () => void;

  feedback: 'correct' | 'wrong' | null;

  onClose: () => void;
};

export default function ChallengeModal({
  challenge,
  index,
  total,
  choice,
  setChoice,
  shortAnswer,
  setShortAnswer,
  onSubmit,
  onContinue,
  feedback,
  onClose,
}: ChallengeModalProps) {

  const isShortAnswer =
    challenge.type === 'short-answer';

  return (
    <div className="absolute inset-0 z-[60] flex items-center justify-center bg-black/65 p-4">

      <div className="panel w-full max-w-xl p-5">

        {/* =====================================================
            HEADER
        ===================================================== */}

        <div className="flex justify-between text-xs text-cyan-300">

          <span>
            CHALLENGE {index} / {total}
          </span>

          <button
            className="retro-btn px-2"
            onClick={onClose}
          >
            X
          </button>

        </div>


        {/* =====================================================
            QUESTION
        ===================================================== */}

        <h2 className="mt-3 text-lg font-black text-white">

          {challenge.question}

        </h2>


        {/* =====================================================
            SHORT ANSWER
        ===================================================== */}

        {isShortAnswer && (

          <div className="mt-5">

            <div className="mb-2 text-xs font-black text-yellow-200">

              ENTER THE KEYWORD

            </div>

            <input
              type="text"
              value={shortAnswer}
              onChange={(event) =>
                setShortAnswer(event.target.value)
              }
              onKeyDown={(event) => {

                if (
                  event.key === 'Enter' &&
                  feedback !== 'correct'
                ) {

                  onSubmit();

                }

              }}
              disabled={
                feedback === 'correct'
              }
              autoFocus
              placeholder="Type your answer..."
              className="w-full border-2 border-cyan-300 bg-black/70 px-4 py-4 text-center text-lg font-black uppercase tracking-widest text-white outline-none placeholder:text-slate-500 focus:border-yellow-300"
            />

          </div>

        )}


        {/* =====================================================
            MULTIPLE CHOICE
        ===================================================== */}

        {!isShortAnswer && (

          <div className="mt-4 grid gap-2">

            {(challenge.options ?? []).map(
              (option, i) => (

                <button
                  key={option}
                  onClick={() =>
                    setChoice(i)
                  }
                  className={`
                    border-2 px-3 py-3 text-left text-sm
                    ${
                      choice === i
                        ? 'border-yellow-300 bg-yellow-300/10'
                        : 'border-slate-600 bg-slate-900/70'
                    }
                    hover:bg-slate-800
                  `}
                >

                  {String.fromCharCode(65 + i)}. {option}

                </button>

              )
            )}

          </div>

        )}


        {/* =====================================================
            WRONG FEEDBACK
        ===================================================== */}

        {feedback === 'wrong' && (

          <div className="mt-4 border border-red-500/60 bg-red-950/30 p-3 text-sm text-red-200">

            Not quite. Review your clues and try again.

          </div>

        )}


        {/* =====================================================
            CORRECT FEEDBACK
        ===================================================== */}

        {feedback === 'correct' && (

          <div className="mt-4 border border-green-500/60 bg-green-950/30 p-3 text-sm text-green-200">

            Correct!

            <div className="mt-2">
              {challenge.explanation}
            </div>

          </div>

        )}


        {/* =====================================================
            SUBMIT / CONTINUE
        ===================================================== */}

        {feedback === 'correct' &&
        isShortAnswer ? (

          <button
            onClick={onContinue}
            className="retro-btn mt-4 w-full py-3 font-black"
          >

            GO TO QUESTIONS →

          </button>

        ) : (

          <button
            disabled={
              feedback === 'correct' ||
              (
                isShortAnswer
                  ? shortAnswer.trim() === ''
                  : choice === null
              )
            }
            onClick={onSubmit}
            className="retro-btn mt-4 w-full py-3 font-black disabled:cursor-not-allowed disabled:opacity-50"
          >

            {feedback === 'correct'
              ? 'CORRECT'
              : 'SUBMIT ANSWER'}

          </button>

        )}

      </div>

    </div>
  );
}